package com.hfr.packet.client;
import com.hfr.packet.effect.XFMenuDataPacket; import com.hfr.packet.PacketDispatcher; import cpw.mods.fml.common.network.simpleimpl.*; import io.netty.buffer.ByteBuf; import net.minecraft.entity.player.EntityPlayerMP;
public class XFMenuDataRequestPacket implements IMessage { public int requestId; public XFMenuDataRequestPacket(){} public XFMenuDataRequestPacket(int requestId){this.requestId=requestId;} public void fromBytes(ByteBuf b){requestId=b.readInt();} public void toBytes(ByteBuf b){b.writeInt(requestId);} public static class Handler implements IMessageHandler<XFMenuDataRequestPacket,IMessage>{ public IMessage onMessage(final XFMenuDataRequestPacket m, MessageContext ctx){ final EntityPlayerMP p=ctx.getServerHandler().playerEntity; com.hfr.tdm.TDMServerTaskQueue.schedule(new Runnable(){public void run(){if(p.playerNetServerHandler==null||!p.playerNetServerHandler.netManager.isChannelOpen())return; PacketDispatcher.wrapper.sendTo(new XFMenuDataPacket(p,m.requestId), p);}}); return null; } } }
